package com.productionhouse.crm.mediahouse.media.api;
import com.productionhouse.crm.mediahouse.media.dto.*;import com.productionhouse.crm.mediahouse.media.service.MediaAssetService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/mediahouse/media") public class MediaAssetController{private final MediaAssetService service;public MediaAssetController(MediaAssetService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('MEDIA_READ')") public Page<MediaAssetResponse> list(@RequestParam(required=false)String q,@RequestParam(required=false)String type,@RequestParam(required=false)String status,@RequestParam(required=false)String projectRef,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return service.list(q,type,status,projectRef,page,size,sort,direction);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('MEDIA_READ')") public MediaAssetResponse get(@PathVariable Long id){return service.get(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('MEDIA_WRITE')") public MediaAssetResponse create(@Valid @RequestBody MediaAssetRequest request){return service.create(request);}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('MEDIA_WRITE')") public MediaAssetResponse update(@PathVariable Long id,@Valid @RequestBody MediaAssetRequest request){return service.update(id,request);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority('MEDIA_DELETE')") public void delete(@PathVariable Long id){service.delete(id);}}
